# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import coverage_gaps

OPENING = parse_span("09:00-17:00")

def _spans(*texts):
    return [parse_span(text) for text in texts]

class CoverageGapTests(unittest.TestCase):
    def test_nobody_working_is_one_gap(self):
        labels = coverage_gaps([], OPENING)
        self.assertEqual(
            labels, ["gap 09:00-17:00 (480 min)"]
        )

    def test_fully_covered_has_no_gaps(self):
        worked = _spans("09:00-17:00")
        self.assertEqual(coverage_gaps(worked, OPENING), [])

    def test_lunch_gap(self):
        worked = _spans("09:00-12:00", "13:00-17:00")
        labels = coverage_gaps(worked, OPENING)
        self.assertEqual(
            labels, ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        worked = _spans("10:00-16:00")
        expected = [
            "gap 09:00-10:00 (60 min)",
            "gap 16:00-17:00 (60 min)",
        ]
        self.assertEqual(
            coverage_gaps(worked, OPENING), expected
        )

    def test_overlaps_do_not_make_false_gaps(self):
        worked = _spans("09:00-13:00", "12:00-14:00")
        labels = coverage_gaps(worked, OPENING)
        self.assertEqual(
            labels, ["gap 14:00-17:00 (180 min)"]
        )

    def test_input_order_does_not_matter(self):
        worked = _spans("13:00-17:00", "09:00-12:00")
        labels = coverage_gaps(worked, OPENING)
        self.assertEqual(
            labels, ["gap 12:00-13:00 (60 min)"]
        )

    def test_work_before_opening_raises(self):
        worked = _spans("08:30-10:00")
        with self.assertRaises(ValueError):
            coverage_gaps(worked, OPENING)

    def test_work_after_closing_raises(self):
        worked = _spans("16:00-17:30")
        with self.assertRaises(ValueError):
            coverage_gaps(worked, OPENING)
